        "volumeExplanation": "10월 30일 3분기 실적 발표 뒤 첫 거래일 전후로 거래량이 평소보다 늘었고, 주가는 60일 신고가를 넘어 마감했다. 다만 발표 직후 반응은 약했다는 보도도 있어 실적 자체가 거래량의 주된 원인인지는 불확실하다. 이후 실적 호조가 반영되는지는 다음 분기 순이익 흐름과 주가가 이 가격대를 지키는지로 확인된다.",
